-- Access QueryDef: Справка_22-10_ОсвСтройки_ПланМесяц
-- Type: 0

SELECT IIf(IsNull([ipgChRsltPlCstPercent]![ogNm]),"итого",[ipgChRsltPlCstPercent]![ogNm]) AS ogNm, IIf(IsNull([ipgChRsltPlCstPercent]![cstAgPnCode]),"всего",[ipgChRsltPlCstPercent]![cstAgPnCode]) AS cstAgPnCode, ags_cstAgPn.cstapCstName, IIf(IsNull([ipgChRsltPlCstPercent]![ag_lim]),0,[ipgChRsltPlCstPercent]![ag_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![iv_lim]),0,[ipgChRsltPlCstPercent]![iv_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![uk_lim]),0,[ipgChRsltPlCstPercent]![uk_lim]) AS lim, ipgChRsltPlCstPercent.ag_lim, IIf([ipgChRsltPlCstPercent]![ag_PlFulfillment]+[ipgChRsltPlCstPercent]![ag_PlOverFulfillment]=0,Null,[ipgChRsltPlCstPercent]![ag_PlFulfillment]+[ipgChRsltPlCstPercent]![ag_PlOverFulfillment]) AS ag_Ful_OverFul, ([ipgChRsltPlCstPercent]![ag_PlFulfillment]+[ipgChRsltPlCstPercent]![ag_PlOverFulfillment])/[ipgChRsltPlCstPercent]![ag_lim] AS ag_LimPc, IIf([ag_PlOverLimit]=0,Null,[ag_PlOverLimit]) AS ag_PlOverLimit_, ipgChRsltPlCstPercent.iv_lim, ipgChRsltPlCstPercent.uk_lim, IIf([ipgChRsltPlCstPercent]![ag_PlAccum]=0,Null,[ipgChRsltPlCstPercent]![ag_PlAccum]) AS ag_PlAccum, IIf([ipgChRsltPlCstPercent]![ag_PlFulfillment]=0,Null,[ipgChRsltPlCstPercent]![ag_PlFulfillment]) AS ag_PlFulfillment, IIf(IsNull([ipgChRsltPlCstPercent]![ag_PlAccum]) Or [ipgChRsltPlCstPercent]![ag_PlAccum]=0,Null,[ipgChRsltPlCstPercent]![ag_PlFulfillment]/[ipgChRsltPlCstPercent]![ag_PlAccum]) AS ag_PlPz, IIf([ipgChRsltPlCstPercent]![ag_PlOverFulfillment]=0,Null,[ipgChRsltPlCstPercent]![ag_PlOverFulfillment]) AS ag_PlOverFulfillment, ipgChRsltPlCstPercent.ag_PlPercent, ipgChRsltPlCstPercent.ag_acceptedTtl AS ag_acceptedTtl_10, ipgChRsltPlCstPercent.ogNm AS 1, ipgChRsltPlCstPercent.cstAgPnCode AS 2
FROM ipgChRsltPlCstPercent LEFT JOIN ags_cstAgPn ON ipgChRsltPlCstPercent.cstAgPnCode = ags_cstAgPn.cstapIpgPnN
WHERE (((IIf(IsNull([ipgChRsltPlCstPercent]![ag_lim]),0,[ipgChRsltPlCstPercent]![ag_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![iv_lim]),0,[ipgChRsltPlCstPercent]![iv_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![uk_lim]),0,[ipgChRsltPlCstPercent]![uk_lim]))>0) AND ((ipgChRsltPlCstPercent.dateRslt)=#10/31/2022#))
ORDER BY ipgChRsltPlCstPercent.ogNm, ipgChRsltPlCstPercent.cstAgPnCode, IIf(IsNull([ipgChRsltPlCstPercent]![ag_lim]),0,[ipgChRsltPlCstPercent]![ag_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![iv_lim]),0,[ipgChRsltPlCstPercent]![iv_lim])+IIf(IsNull([ipgChRsltPlCstPercent]![uk_lim]),0,[ipgChRsltPlCstPercent]![uk_lim]) DESC , ipgChRsltPlCstPercent.dateRslt;
